const namespace = process.env.BOUNTYBOX_TRIAL_NAMESPACE;
let databaseConfigured = false;
try {
  const url = new URL(process.env.NEON_DATABASE_URL);
  databaseConfigured = ['postgres:', 'postgresql:'].includes(url.protocol) && url.hostname.endsWith('.neon.tech') && url.hostname.split('.').length >= 4 && url.hostname.startsWith('ep-');
} catch {}
const checks = {
  nodeSupported: Number(process.versions.node.split('.')[0]) >= 22,
  databaseConfigured,
  ingressConfigured: Boolean(process.env.BOUNTYBOX_INGRESS_TOKEN),
  namespaceValid: typeof namespace === 'string' && /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/.test(namespace)
};
console.log(JSON.stringify({ diagnosticOnly: true, checks }));
process.exitCode = Object.values(checks).every(Boolean) ? 0 : 1;

import http from 'node:http';
import { createHash, timingSafeEqual } from 'node:crypto';

const token = process.env.BOUNTYBOX_INGRESS_TOKEN;
const namespace = process.env.BOUNTYBOX_TRIAL_NAMESPACE;
const connection = process.env.NEON_DATABASE_URL;
if (!token || !connection || !namespace || !/^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/.test(namespace)) {
  console.error('Required configuration is missing or invalid.');
  process.exit(1);
}
let endpoint;
try {
  const url = new URL(connection);
  if (!['postgres:', 'postgresql:'].includes(url.protocol) || !url.hostname.endsWith('.neon.tech')) throw new Error();
  const labels = url.hostname.split('.');
  if (labels.length < 4 || !labels[0].startsWith('ep-')) throw new Error();
  labels[0] = 'api';
  endpoint = `https://${labels.join('.')}/sql`;
} catch {
  console.error('Database configuration is invalid.');
  process.exit(1);
}
const port = Number(process.env.PORT ?? 3000);
if (!Number.isInteger(port) || port < 1 || port > 65535) {
  console.error('Port configuration is invalid.');
  process.exit(1);
}
const table = `"waitlist_${createHash('sha256').update(namespace).digest('hex').slice(0, 48)}"`;
const expectedAuth = createHash('sha256').update(`Bearer ${token}`).digest();

// All statements used here are safe to retry, including inserts with ON CONFLICT.
// Bound both attempts so a stalled database request cannot consume five seconds.
async function sql(query, params = [], startup = false) {
  const deadline = Date.now() + (startup ? 20000 : 1700);
  for (let attempt = 0; attempt < 2; attempt++) {
    const remaining = deadline - Date.now();
    if (remaining <= 0) break;
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        redirect: 'error',
        signal: AbortSignal.timeout(Math.max(1, Math.min(startup ? 10000 : 800, remaining))),
        headers: {
          'Neon-Connection-String': connection,
          'Content-Type': 'application/json',
          'Neon-Array-Mode': 'true',
          'Neon-Raw-Text-Output': 'true'
        },
        body: JSON.stringify({ query, params })
      });
      if (!response.ok) {
        await response.body?.cancel();
        if (response.status < 500 && response.status !== 429) break;
        continue;
      }
      const result = await response.json();
      if (!Array.isArray(result.rows)) break;
      return result;
    } catch {
      // Never expose transport errors, response bodies, or connection details.
    }
  }
  throw new Error('Database request failed');
}

function reply(res, status, value) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(value));
}

async function readBody(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req.iterator({ destroyOnReturn: false })) {
    size += chunk.length;
    if (size > 16384) {
      req.resume();
      throw Object.assign(new Error('Body too large'), { status: 413 });
    }
    chunks.push(chunk);
  }
  return Buffer.concat(chunks).toString('utf8');
}

function validEmail(email) {
  if (email.length > 254) return false;
  const parts = email.split('@');
  if (parts.length !== 2) return false;
  const [local, domain] = parts;
  if (!local || local.length > 64 || !/^[a-z0-9.!#$%&'*+/=?^_`{|}~-]+$/.test(local)) return false;
  if (local.startsWith('.') || local.endsWith('.') || local.includes('..')) return false;
  const labels = domain.split('.');
  return labels.length >= 2 && labels.every(label => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label));
}

try {
  await sql(`CREATE TABLE IF NOT EXISTS ${table} (email TEXT PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT now())`, [], true);
  await sql(`SELECT COUNT(*) FROM ${table}`, [], true);
} catch {
  console.error('Database initialization failed.');
  process.exit(1);
}

const server = http.createServer(async (req, res) => {
  const suppliedAuth = createHash('sha256').update(req.headers.authorization ?? '').digest();
  if (!timingSafeEqual(expectedAuth, suppliedAuth)) {
    req.resume();
    reply(res, 401, { error: 'Unauthorized' });
    return;
  }
  if (req.headers['content-length'] !== undefined && (!/^\d+$/.test(req.headers['content-length']) || Number(req.headers['content-length']) > 16384)) {
    req.resume();
    reply(res, 413, { error: 'Request body too large' });
    return;
  }
  try {
    const path = new URL(req.url, 'http://localhost').pathname;
    const raw = await readBody(req);
    if (req.method === 'GET' && path === '/health') {
      reply(res, 200, { ok: true, artifactDigest: process.env.BOUNTYBOX_ARTIFACT_DIGEST });
    } else if (req.method === 'GET' && path === '/stats') {
      const result = await sql(`SELECT COUNT(*) FROM ${table}`);
      const count = Number(result.rows[0][0]);
      if (!Number.isSafeInteger(count) || count < 0) throw new Error('Invalid count');
      reply(res, 200, { count });
    } else if (req.method === 'POST' && path === '/signups') {
      let body;
      try { body = JSON.parse(raw); }
      catch { throw Object.assign(new Error('Invalid JSON'), { status: 400 }); }
      const email = typeof body?.email === 'string' ? body.email.trim().toLowerCase() : '';
      if (!validEmail(email)) {
        reply(res, 400, { error: 'A valid email is required' });
        return;
      }
      const result = await sql(`INSERT INTO ${table} (email) VALUES ($1) ON CONFLICT (email) DO NOTHING RETURNING email`, [email]);
      const row = result.rows[0];
      reply(res, row ? 201 : 200, { email: row ? row[0] : email, created: Boolean(row) });
    } else {
      reply(res, 404, { error: 'Not found' });
    }
  } catch (error) {
    if (!res.destroyed && !res.headersSent) {
      const status = error.status === 413 ? 413 : error.status === 400 ? 400 : 503;
      reply(res, status, { error: status === 413 ? 'Request body too large' : status === 400 ? 'Invalid JSON' : 'Service unavailable' });
    }
  }
});
server.requestTimeout = 10000;
server.headersTimeout = 10000;
server.keepAliveTimeout = 60000;
server.on('error', () => {
  console.error('HTTP server failed.');
  process.exit(1);
});
server.listen(port, '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(0), 10000).unref();
  });
}
